-- DSU-CFCS 1.0. PostgreSQL 16+. All thresholds and academic rules are data, not defaults.
CREATE TABLE schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schools(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, deleted_at timestamptz);
CREATE TABLE departments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, school_id bigint NOT NULL REFERENCES schools, code text UNIQUE NOT NULL, name text NOT NULL, deleted_at timestamptz);
CREATE TABLE programmes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, department_id bigint NOT NULL REFERENCES departments, code text UNIQUE NOT NULL, name text NOT NULL, semesters smallint NOT NULL CHECK(semesters BETWEEN 1 AND 20), deleted_at timestamptz);
CREATE TABLE academic_years(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label text UNIQUE NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, CHECK(ends_on>starts_on));
CREATE TABLE admission_batches(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, year integer UNIQUE NOT NULL, deleted_at timestamptz);
CREATE TABLE curriculum_semesters(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, number smallint NOT NULL UNIQUE CHECK(number BETWEEN 1 AND 20), deleted_at timestamptz);
CREATE TABLE regulations(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, active boolean NOT NULL, floating_window smallint NOT NULL CHECK(floating_window IN(0,1)), conditional_allowed boolean NOT NULL, attendance_threshold numeric CHECK(attendance_threshold BETWEEN 0 AND 100), block_on_shortage boolean NOT NULL DEFAULT false, block_unrelated boolean NOT NULL DEFAULT false, priority_order text[] NOT NULL DEFAULT ARRAY['P1','P2','P3','P4','P5'], approved_by bigint, approved_at timestamptz, deleted_at timestamptz);
CREATE TABLE graduation_requirements(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, regulation_id bigint NOT NULL REFERENCES regulations, programme_id bigint NOT NULL REFERENCES programmes, total_credits numeric NOT NULL CHECK(total_credits>0), mandatory_credits numeric NOT NULL CHECK(mandatory_credits>=0), elective_credits numeric NOT NULL CHECK(elective_credits>=0), UNIQUE(regulation_id,programme_id));
CREATE TABLE course_categories(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, elective boolean NOT NULL DEFAULT false, deleted_at timestamptz);
CREATE TABLE assessment_schemes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, regulation_id bigint NOT NULL REFERENCES regulations, description text NOT NULL, UNIQUE(name,regulation_id));
CREATE TABLE courses(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL, title text NOT NULL, programme_id bigint NOT NULL REFERENCES programmes, regulation_id bigint NOT NULL REFERENCES regulations, semester_id bigint NOT NULL REFERENCES curriculum_semesters, category_id bigint NOT NULL REFERENCES course_categories, credits numeric(5,2) NOT NULL CHECK(credits>0), lecture smallint NOT NULL CHECK(lecture>=0), tutorial smallint NOT NULL CHECK(tutorial>=0), practical smallint NOT NULL CHECK(practical>=0), assessment_id bigint NOT NULL REFERENCES assessment_schemes, approved boolean NOT NULL DEFAULT false, deleted_at timestamptz, UNIQUE(code,regulation_id,programme_id));
CREATE TABLE course_prerequisite_groups(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES courses, name text NOT NULL, operator text NOT NULL CHECK(operator IN('AND','OR')), kind text NOT NULL CHECK(kind IN('Mandatory','Conditional','Recommended')), UNIQUE(course_id,name));
CREATE TABLE course_prerequisites(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_id bigint NOT NULL REFERENCES course_prerequisite_groups ON DELETE CASCADE, prerequisite_id bigint NOT NULL REFERENCES courses, UNIQUE(group_id,prerequisite_id));
CREATE TABLE course_equivalences(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_a bigint NOT NULL REFERENCES courses, course_b bigint NOT NULL REFERENCES courses, approved boolean NOT NULL DEFAULT false, recognise_credit boolean NOT NULL DEFAULT false, valid_from date NOT NULL, valid_until date NOT NULL, approved_by bigint, CHECK(course_a<course_b), CHECK(valid_until>=valid_from), UNIQUE(course_a,course_b));
CREATE TABLE faculty(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, staff_number text NOT NULL UNIQUE, name text NOT NULL, department_id bigint NOT NULL REFERENCES departments, specialisation text NOT NULL, lab_competent boolean NOT NULL DEFAULT false, deleted_at timestamptz);
CREATE TABLE faculty_qualifications(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, faculty_id bigint NOT NULL REFERENCES faculty, qualification text NOT NULL, UNIQUE(faculty_id,qualification));
CREATE TABLE faculty_course_competencies(faculty_id bigint NOT NULL REFERENCES faculty, course_id bigint NOT NULL REFERENCES courses, approved boolean NOT NULL DEFAULT false, PRIMARY KEY(faculty_id,course_id));
CREATE TABLE faculty_workloads(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, faculty_id bigint NOT NULL REFERENCES faculty, academic_year_id bigint NOT NULL REFERENCES academic_years, maximum_hours numeric NOT NULL CHECK(maximum_hours>0), other_hours numeric NOT NULL CHECK(other_hours>=0), UNIQUE(faculty_id,academic_year_id));
CREATE TABLE faculty_availability(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, faculty_id bigint NOT NULL REFERENCES faculty, weekday smallint NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts integer NOT NULL, ends integer NOT NULL, CHECK(starts>=0 AND ends<=1440 AND starts<ends));
CREATE TABLE students(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, register_number text NOT NULL UNIQUE, name text NOT NULL, programme_id bigint NOT NULL REFERENCES programmes, regulation_id bigint NOT NULL REFERENCES regulations, batch_id bigint NOT NULL REFERENCES admission_batches, semester_id bigint NOT NULL REFERENCES curriculum_semesters, status text NOT NULL CHECK(status IN('Active','Restricted','Graduated','On leave')), category text NOT NULL DEFAULT 'General', advisor_id bigint REFERENCES faculty, deleted_at timestamptz);
CREATE TABLE student_academic_records(student_id bigint PRIMARY KEY REFERENCES students, cgpa numeric(4,2) CHECK(cgpa BETWEEN 0 AND 10), verified_at timestamptz, note text NOT NULL DEFAULT '');
CREATE TABLE student_course_results(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, course_id bigint NOT NULL REFERENCES courses, attempt integer NOT NULL CHECK(attempt>0), outcome text NOT NULL CHECK(outcome IN('Passed','Failed','Debarred')), verified boolean NOT NULL DEFAULT false, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(student_id,course_id,attempt));
CREATE TABLE attendance_records(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, course_id bigint NOT NULL REFERENCES courses, academic_year_id bigint NOT NULL REFERENCES academic_years, attended integer NOT NULL, conducted integer NOT NULL, status text NOT NULL CHECK(status IN('Eligible','Shortage','Debarred','Approved exception')), repeat_approved boolean NOT NULL DEFAULT false, CHECK(conducted>0 AND attended BETWEEN 0 AND conducted), UNIQUE(student_id,course_id,academic_year_id));
CREATE TABLE pending_requirements(student_id bigint NOT NULL REFERENCES students, course_id bigint NOT NULL REFERENCES courses, approved boolean NOT NULL DEFAULT false, PRIMARY KEY(student_id,course_id));
CREATE TABLE roles(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL UNIQUE);
CREATE TABLE permissions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE role_permissions(role_id bigint REFERENCES roles, permission_id bigint REFERENCES permissions, PRIMARY KEY(role_id,permission_id));
CREATE TABLE users(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username text NOT NULL UNIQUE, name text NOT NULL, password_hash text, role_id bigint NOT NULL REFERENCES roles, department_id bigint REFERENCES departments, student_id bigint REFERENCES students, faculty_id bigint REFERENCES faculty, active boolean NOT NULL DEFAULT true, demo boolean NOT NULL DEFAULT false);
ALTER TABLE regulations ADD CONSTRAINT regulation_approver_fk FOREIGN KEY(approved_by) REFERENCES users;
ALTER TABLE course_equivalences ADD CONSTRAINT equivalence_approver_fk FOREIGN KEY(approved_by) REFERENCES users;
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES users, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_attempts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, client_key text NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX login_rate_idx ON login_attempts(client_key,attempted_at);
CREATE TABLE classrooms(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code text UNIQUE NOT NULL, capacity integer NOT NULL CHECK(capacity>0), deleted_at timestamptz);
CREATE TABLE laboratories(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, classroom_id bigint NOT NULL UNIQUE REFERENCES classrooms, speciality text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), deleted_at timestamptz);
CREATE TABLE registration_windows(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name text NOT NULL, opens_at timestamptz NOT NULL, closes_at timestamptz NOT NULL, academic_year_id bigint NOT NULL REFERENCES academic_years, CHECK(closes_at>opens_at));
CREATE TABLE credit_limits(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, regulation_id bigint NOT NULL REFERENCES regulations, programme_id bigint NOT NULL REFERENCES programmes, semester_id bigint REFERENCES curriculum_semesters, academic_year_id bigint NOT NULL REFERENCES academic_years, category text, minimum_credits numeric NOT NULL CHECK(minimum_credits>=0), maximum_credits numeric NOT NULL, CHECK(maximum_credits>=minimum_credits), UNIQUE NULLS NOT DISTINCT(regulation_id,programme_id,semester_id,academic_year_id,category));
CREATE TABLE course_offerings(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, course_id bigint NOT NULL REFERENCES courses, department_id bigint NOT NULL REFERENCES departments, academic_year_id bigint NOT NULL REFERENCES academic_years, window_id bigint NOT NULL REFERENCES registration_windows, status text NOT NULL CHECK(status IN('Draft','Pending approval','Published','Withdrawn')), recovery_allowed boolean NOT NULL DEFAULT false, approved_by bigint REFERENCES users, deleted_at timestamptz);
CREATE TABLE offering_mappings(offering_id bigint NOT NULL REFERENCES course_offerings, course_id bigint NOT NULL REFERENCES courses, PRIMARY KEY(offering_id,course_id));
CREATE TABLE course_sections(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, offering_id bigint NOT NULL REFERENCES course_offerings, label text NOT NULL, faculty_id bigint REFERENCES faculty, maximum_seats integer NOT NULL CHECK(maximum_seats>0), minimum_seats integer NOT NULL CHECK(minimum_seats>=0), reserved_seats integer NOT NULL DEFAULT 0, CHECK(minimum_seats<=maximum_seats AND reserved_seats BETWEEN 0 AND maximum_seats), UNIQUE(offering_id,label));
CREATE TABLE timetable_slots(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, section_id bigint NOT NULL REFERENCES course_sections, room_id bigint NOT NULL REFERENCES classrooms, weekday smallint NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts integer NOT NULL, ends integer NOT NULL, kind text NOT NULL CHECK(kind IN('Theory','Tutorial','Practical')), CHECK(starts>=0 AND ends<=1440 AND starts<ends));
CREATE TABLE course_enrolments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, section_id bigint NOT NULL REFERENCES course_sections, course_id bigint NOT NULL REFERENCES courses, academic_year_id bigint NOT NULL REFERENCES academic_years, basket text NOT NULL CHECK(basket IN('Regular','Floating','Backlog','Repeat')), priority text NOT NULL, status text NOT NULL CHECK(status IN('Registered','Waitlisted','Pending approval','Dropped','Rejected')), created_at timestamptz NOT NULL DEFAULT now(), changed_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX no_duplicate_active_course ON course_enrolments(student_id,course_id,academic_year_id) WHERE status IN('Registered','Waitlisted','Pending approval');
CREATE UNIQUE INDEX no_duplicate_active_section ON course_enrolments(student_id,section_id,academic_year_id) WHERE status IN('Registered','Waitlisted','Pending approval');
CREATE TABLE course_preferences(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, course_id bigint NOT NULL REFERENCES courses, academic_year_id bigint NOT NULL REFERENCES academic_years, rank smallint NOT NULL CHECK(rank BETWEEN 1 AND 3), interest text NOT NULL CHECK(interest IN('Core','Floating','Open elective')), UNIQUE(student_id,academic_year_id,rank), UNIQUE(student_id,academic_year_id,course_id));
CREATE TABLE academic_exceptions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, course_id bigint REFERENCES courses, kind text NOT NULL CHECK(kind IN('Conditional prerequisite','Credit overload','Course equivalence','Special offering','Timetable','Academic progression','Attendance exception')), reason text NOT NULL, evidence text NOT NULL, requested_by bigint NOT NULL REFERENCES users, authority text NOT NULL REFERENCES roles(name), status text NOT NULL CHECK(status IN('Pending','Approved','Rejected')), extra_credits numeric NOT NULL DEFAULT 0 CHECK(extra_credits>=0), academic_year_id bigint NOT NULL REFERENCES academic_years, requested_at timestamptz NOT NULL DEFAULT now(), decided_by bigint REFERENCES users, remarks text, decided_at timestamptz);
CREATE TABLE registration_approvals(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, enrolment_id bigint REFERENCES course_enrolments, student_id bigint NOT NULL REFERENCES students, academic_year_id bigint NOT NULL REFERENCES academic_years, authority_id bigint NOT NULL REFERENCES users, decision text NOT NULL, remarks text NOT NULL, decided_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE regulation_migrations(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id bigint NOT NULL REFERENCES students, from_regulation bigint NOT NULL REFERENCES regulations, to_regulation bigint NOT NULL REFERENCES regulations, reason text NOT NULL, approved_by bigint NOT NULL REFERENCES users, approved_at timestamptz NOT NULL DEFAULT now(), CHECK(from_regulation<>to_regulation));
CREATE TABLE academic_audit_logs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id bigint REFERENCES users, action text NOT NULL, entity text NOT NULL, entity_id bigint, detail jsonb NOT NULL DEFAULT '{}', recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_batches(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users, kind text NOT NULL, filename text NOT NULL, payload jsonb NOT NULL, summary jsonb NOT NULL, committed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_metadata(key text PRIMARY KEY, value text NOT NULL);
CREATE INDEX student_scope_idx ON students(programme_id,regulation_id,semester_id); CREATE INDEX result_lookup_idx ON student_course_results(student_id,course_id,verified); CREATE INDEX seat_queue_idx ON course_enrolments(section_id,status,priority,created_at); CREATE INDEX slot_clash_idx ON timetable_slots(weekday,starts,ends); CREATE INDEX attendance_status_idx ON attendance_records(status,student_id); CREATE INDEX exception_queue_idx ON academic_exceptions(status,authority); CREATE INDEX enrolment_year_idx ON course_enrolments(academic_year_id,status,created_at); CREATE INDEX audit_time_idx ON academic_audit_logs(recorded_at DESC);
CREATE FUNCTION protect_audit_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Academic audit history is append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON academic_audit_logs FOR EACH ROW EXECUTE FUNCTION protect_audit_history();
INSERT INTO schema_migrations(version) VALUES('001_foundation');
